INSERT INTO recipe_method_steps (
  id, recipe_id, family_id, step_text, position
) VALUES
(gen_random_uuid(), 'be1d1d0c-1157-5561-bc14-5fed2394c79a', NULL, 'Season chicken with salt, pepper, and Italian herbs.', 0),(gen_random_uuid(), 'be1d1d0c-1157-5561-bc14-5fed2394c79a', NULL, 'Sear chicken in a hot pan until golden, about 4 minutes per side. Set aside.', 1),(gen_random_uuid(), 'be1d1d0c-1157-5561-bc14-5fed2394c79a', NULL, 'In the same pan, sauté garlic and sun-dried tomatoes for 1 minute.', 2),(gen_random_uuid(), 'be1d1d0c-1157-5561-bc14-5fed2394c79a', NULL, 'Pour in cream and stir in parmesan until melted.', 3),(gen_random_uuid(), 'be1d1d0c-1157-5561-bc14-5fed2394c79a', NULL, 'Add spinach and let it wilt into the sauce.', 4),(gen_random_uuid(), 'be1d1d0c-1157-5561-bc14-5fed2394c79a', NULL, 'Return chicken to the pan and simmer for 5 minutes.', 5),(gen_random_uuid(), '8c230ce7-70c6-54f4-a9d6-b81e8139f2ca', NULL, 'Cook sushi rice according to packet instructions.', 0),(gen_random_uuid(), '8c230ce7-70c6-54f4-a9d6-b81e8139f2ca', NULL, 'Mix soy sauce, mirin, and honey for the teriyaki glaze.', 1),(gen_random_uuid(), '8c230ce7-70c6-54f4-a9d6-b81e8139f2ca', NULL, 'Pan-sear salmon skin-side down for 3 minutes, flip and glaze.', 2),(gen_random_uuid(), '8c230ce7-70c6-54f4-a9d6-b81e8139f2ca', NULL, 'Assemble bowls with rice, sliced salmon, avocado, and edamame.', 3),(gen_random_uuid(), '8c230ce7-70c6-54f4-a9d6-b81e8139f2ca', NULL, 'Drizzle remaining glaze and serve with sesame seeds.', 4),(gen_random_uuid(), 'ff5e24fd-36a1-5072-99e2-1c3f74601bb9', NULL, 'Marinate chicken in lime juice, cumin, paprika, and garlic for 15 minutes.', 0),(gen_random_uuid(), 'ff5e24fd-36a1-5072-99e2-1c3f74601bb9', NULL, 'Grill or pan-fry chicken until charred and cooked through.', 1),(gen_random_uuid(), 'ff5e24fd-36a1-5072-99e2-1c3f74601bb9', NULL, 'Warm tortillas in a dry pan.', 2),(gen_random_uuid(), 'ff5e24fd-36a1-5072-99e2-1c3f74601bb9', NULL, 'Dice red onion, chop coriander, and slice avocado.', 3),(gen_random_uuid(), 'ff5e24fd-36a1-5072-99e2-1c3f74601bb9', NULL, 'Slice chicken and assemble tacos with fresh toppings.', 4),(gen_random_uuid(), 'ff5e24fd-36a1-5072-99e2-1c3f74601bb9', NULL, 'Squeeze fresh lime over the top and serve.', 5),(gen_random_uuid(), '25195c59-bf53-5f66-b663-e73e7a73688a', NULL, 'Mix lamb mince with cumin, coriander, salt, and pepper.', 0),(gen_random_uuid(), '25195c59-bf53-5f66-b663-e73e7a73688a', NULL, 'Shape into oval kofta on skewers.', 1),(gen_random_uuid(), '25195c59-bf53-5f66-b663-e73e7a73688a', NULL, 'Grill or pan-fry for 4 minutes each side.', 2),(gen_random_uuid(), '25195c59-bf53-5f66-b663-e73e7a73688a', NULL, 'Make tzatziki by grating cucumber into yoghurt with garlic and mint.', 3),(gen_random_uuid(), '25195c59-bf53-5f66-b663-e73e7a73688a', NULL, 'Serve kofta with salad, feta, and warm flatbread.', 4),(gen_random_uuid(), '4ae0a49c-8469-5414-9e92-ac8c894da444', NULL, 'Marinate chicken in yoghurt and spices for at least 30 minutes.', 0),(gen_random_uuid(), '4ae0a49c-8469-5414-9e92-ac8c894da444', NULL, 'Sear chicken pieces in butter until browned.', 1),(gen_random_uuid(), '4ae0a49c-8469-5414-9e92-ac8c894da444', NULL, 'Add onion, garlic, and ginger paste. Cook until fragrant.', 2),(gen_random_uuid(), '4ae0a49c-8469-5414-9e92-ac8c894da444', NULL, 'Pour in tomato passata and simmer for 15 minutes.', 3),(gen_random_uuid(), '4ae0a49c-8469-5414-9e92-ac8c894da444', NULL, 'Stir in cream and garam masala. Simmer 10 more minutes.', 4),(gen_random_uuid(), '4ae0a49c-8469-5414-9e92-ac8c894da444', NULL, 'Serve over fluffy basmati rice with naan on the side.', 5),(gen_random_uuid(), '11c3e526-bda6-504d-9ce3-c127d752f43b', NULL, 'Sauté mushrooms in butter until golden. Set aside.', 0),(gen_random_uuid(), '11c3e526-bda6-504d-9ce3-c127d752f43b', NULL, 'Toast rice in the same pan with diced onion.', 1),(gen_random_uuid(), '11c3e526-bda6-504d-9ce3-c127d752f43b', NULL, 'Deglaze with white wine and stir until absorbed.', 2),(gen_random_uuid(), '11c3e526-bda6-504d-9ce3-c127d752f43b', NULL, 'Add warm stock one ladle at a time, stirring continuously.', 3),(gen_random_uuid(), '11c3e526-bda6-504d-9ce3-c127d752f43b', NULL, 'When rice is al dente, fold in mushrooms, parmesan, and a knob of butter.', 4),(gen_random_uuid(), '11c3e526-bda6-504d-9ce3-c127d752f43b', NULL, 'Season and serve immediately with extra parmesan.', 5),(gen_random_uuid(), 'bd677dd2-b0d2-5a1d-908a-4cf2e2c7412d', NULL, 'Soak rice noodles in warm water for 10 minutes, drain.', 0),(gen_random_uuid(), 'bd677dd2-b0d2-5a1d-908a-4cf2e2c7412d', NULL, 'Scramble eggs in a hot wok, set aside.', 1),(gen_random_uuid(), 'bd677dd2-b0d2-5a1d-908a-4cf2e2c7412d', NULL, 'Stir-fry prawns until pink, about 2 minutes.', 2),(gen_random_uuid(), 'bd677dd2-b0d2-5a1d-908a-4cf2e2c7412d', NULL, 'Add noodles, tamarind sauce, fish sauce, and sugar.', 3),(gen_random_uuid(), 'bd677dd2-b0d2-5a1d-908a-4cf2e2c7412d', NULL, 'Toss in bean sprouts and scrambled egg.', 4),(gen_random_uuid(), 'bd677dd2-b0d2-5a1d-908a-4cf2e2c7412d', NULL, 'Serve with crushed peanuts and lime wedges.', 5),(gen_random_uuid(), 'aff73d9b-3d45-50fe-aba8-3bc282a9f57c', NULL, 'Sauté diced peppers and onion in olive oil until soft.', 0),(gen_random_uuid(), 'aff73d9b-3d45-50fe-aba8-3bc282a9f57c', NULL, 'Add cumin, paprika, and chilli flakes. Stir for 30 seconds.', 1),(gen_random_uuid(), 'aff73d9b-3d45-50fe-aba8-3bc282a9f57c', NULL, 'Pour in tomatoes, season, and simmer for 10 minutes.', 2),(gen_random_uuid(), 'aff73d9b-3d45-50fe-aba8-3bc282a9f57c', NULL, 'Make wells in the sauce and crack in eggs.', 3),(gen_random_uuid(), 'aff73d9b-3d45-50fe-aba8-3bc282a9f57c', NULL, 'Cover and cook until whites are set, about 8 minutes.', 4),(gen_random_uuid(), 'aff73d9b-3d45-50fe-aba8-3bc282a9f57c', NULL, 'Crumble feta on top and serve with crusty bread.', 5),(gen_random_uuid(), 'dbb1da6d-e192-529a-9a96-fc7c6b532858', NULL, 'Fry curry paste in a splash of coconut milk until fragrant.', 0),(gen_random_uuid(), 'dbb1da6d-e192-529a-9a96-fc7c6b532858', NULL, 'Add sliced chicken and cook for 3 minutes.', 1),(gen_random_uuid(), 'dbb1da6d-e192-529a-9a96-fc7c6b532858', NULL, 'Pour in remaining coconut milk and simmer for 10 minutes.', 2),(gen_random_uuid(), 'dbb1da6d-e192-529a-9a96-fc7c6b532858', NULL, 'Add vegetables and Thai basil. Cook 2 more minutes.', 3),(gen_random_uuid(), 'dbb1da6d-e192-529a-9a96-fc7c6b532858', NULL, 'Serve over jasmine rice.', 4),(gen_random_uuid(), 'dd907379-fa41-521c-ace2-8c9237f04b65', NULL, 'Cook pasta according to instructions. Reserve pasta water.', 0),(gen_random_uuid(), 'dd907379-fa41-521c-ace2-8c9237f04b65', NULL, 'Halve cherry tomatoes and tear mozzarella.', 1),(gen_random_uuid(), 'dd907379-fa41-521c-ace2-8c9237f04b65', NULL, 'Toss hot pasta with tomatoes, mozzarella, and olive oil.', 2),(gen_random_uuid(), 'dd907379-fa41-521c-ace2-8c9237f04b65', NULL, 'Add a splash of pasta water and balsamic vinegar.', 3),(gen_random_uuid(), 'dd907379-fa41-521c-ace2-8c9237f04b65', NULL, 'Tear basil over the top and serve immediately.', 4),(gen_random_uuid(), '9bd94e56-f1d4-55d1-9ac0-f09af4fac6b6', NULL, 'Cook rice and keep warm.', 0),(gen_random_uuid(), '9bd94e56-f1d4-55d1-9ac0-f09af4fac6b6', NULL, 'Season and cook beef in soy sauce and sesame oil.', 1),(gen_random_uuid(), '9bd94e56-f1d4-55d1-9ac0-f09af4fac6b6', NULL, 'Blanch spinach and julienne and sauté carrots separately.', 2),(gen_random_uuid(), '9bd94e56-f1d4-55d1-9ac0-f09af4fac6b6', NULL, 'Fry eggs sunny-side up.', 3),(gen_random_uuid(), '9bd94e56-f1d4-55d1-9ac0-f09af4fac6b6', NULL, 'Arrange rice in bowls, top with vegetables, beef, and egg.', 4),(gen_random_uuid(), '9bd94e56-f1d4-55d1-9ac0-f09af4fac6b6', NULL, 'Serve with gochujang sauce on the side.', 5),(gen_random_uuid(), 'ac84cc91-cfc6-55c1-b56a-09099c0ecb6b', NULL, 'Rinse lentils and add to a pot with water and turmeric.', 0),(gen_random_uuid(), 'ac84cc91-cfc6-55c1-b56a-09099c0ecb6b', NULL, 'Simmer for 20 minutes until soft and creamy.', 1),(gen_random_uuid(), 'ac84cc91-cfc6-55c1-b56a-09099c0ecb6b', NULL, 'In a separate pan, temper mustard seeds, cumin, and garlic in oil.', 2),(gen_random_uuid(), 'ac84cc91-cfc6-55c1-b56a-09099c0ecb6b', NULL, 'Pour the tempering into the lentils with coconut milk.', 3),(gen_random_uuid(), 'ac84cc91-cfc6-55c1-b56a-09099c0ecb6b', NULL, 'Season and garnish with fresh coriander.', 4),(gen_random_uuid(), 'ac84cc91-cfc6-55c1-b56a-09099c0ecb6b', NULL, 'Serve with warm naan bread.', 5),(gen_random_uuid(), '2503dc9f-4a9e-5b4d-b034-059133308d91', NULL, 'Combine oats, chia seeds, and oat milk in two jars or bowls.', 0),(gen_random_uuid(), '2503dc9f-4a9e-5b4d-b034-059133308d91', NULL, 'Stir in maple syrup and a pinch of salt.', 1),(gen_random_uuid(), '2503dc9f-4a9e-5b4d-b034-059133308d91', NULL, 'Cover and refrigerate overnight or for at least 4 hours.', 2),(gen_random_uuid(), '2503dc9f-4a9e-5b4d-b034-059133308d91', NULL, 'In the morning, top with mixed berries and a drizzle of almond butter.', 3),(gen_random_uuid(), '2503dc9f-4a9e-5b4d-b034-059133308d91', NULL, 'Serve cold straight from the fridge.', 4),(gen_random_uuid(), 'a253bc39-e541-545c-803c-5b0a0141aff5', NULL, 'Toast sourdough slices until golden and crisp.', 0),(gen_random_uuid(), 'a253bc39-e541-545c-803c-5b0a0141aff5', NULL, 'Mash avocado with lemon juice, salt, and pepper.', 1),(gen_random_uuid(), 'a253bc39-e541-545c-803c-5b0a0141aff5', NULL, 'Bring a pot of water to a gentle simmer. Add vinegar.', 2),(gen_random_uuid(), 'a253bc39-e541-545c-803c-5b0a0141aff5', NULL, 'Crack each egg into a cup and slide gently into the water.', 3),(gen_random_uuid(), 'a253bc39-e541-545c-803c-5b0a0141aff5', NULL, 'Poach for 3 minutes until whites are set but yolk is still runny.', 4),(gen_random_uuid(), 'a253bc39-e541-545c-803c-5b0a0141aff5', NULL, 'Spread avocado on toast, top with poached egg and chilli flakes.', 5),(gen_random_uuid(), 'd67d0095-d290-55ce-bb8b-a8f9c41a813d', NULL, 'Finely dice onion, tomato, green chilli, and coriander.', 0),(gen_random_uuid(), 'd67d0095-d290-55ce-bb8b-a8f9c41a813d', NULL, 'Beat eggs with turmeric, salt, and a splash of water.', 1),(gen_random_uuid(), 'd67d0095-d290-55ce-bb8b-a8f9c41a813d', NULL, 'Stir the vegetables into the egg mixture.', 2),(gen_random_uuid(), 'd67d0095-d290-55ce-bb8b-a8f9c41a813d', NULL, 'Heat oil in a pan over medium heat.', 3),(gen_random_uuid(), 'd67d0095-d290-55ce-bb8b-a8f9c41a813d', NULL, 'Pour in the egg mixture and cook until edges are set.', 4),(gen_random_uuid(), 'd67d0095-d290-55ce-bb8b-a8f9c41a813d', NULL, 'Fold in half and serve hot with toast or roti.', 5),(gen_random_uuid(), '49d33cc9-04b6-5d98-a91d-1383e4481580', NULL, 'Mash bananas in a bowl until smooth.', 0),(gen_random_uuid(), '49d33cc9-04b6-5d98-a91d-1383e4481580', NULL, 'Beat in eggs, flour, and milk until a batter forms.', 1),(gen_random_uuid(), '49d33cc9-04b6-5d98-a91d-1383e4481580', NULL, 'Heat butter in a non-stick pan over medium heat.', 2),(gen_random_uuid(), '49d33cc9-04b6-5d98-a91d-1383e4481580', NULL, 'Pour small rounds of batter and cook for 2 minutes each side.', 3),(gen_random_uuid(), '49d33cc9-04b6-5d98-a91d-1383e4481580', NULL, 'Serve stacked with maple syrup and fresh fruit.', 4),(gen_random_uuid(), 'a4c38fa6-8361-5f40-bf5a-e45ade76af30', NULL, 'Cook rice and keep warm.', 0),(gen_random_uuid(), 'a4c38fa6-8361-5f40-bf5a-e45ade76af30', NULL, 'Beat eggs with soy sauce and sesame oil.', 1),(gen_random_uuid(), 'a4c38fa6-8361-5f40-bf5a-e45ade76af30', NULL, 'Pour egg mixture over hot rice and stir quickly — the heat cooks the egg into a silky sauce.', 2),(gen_random_uuid(), 'a4c38fa6-8361-5f40-bf5a-e45ade76af30', NULL, 'Top with sliced spring onion and sesame seeds.', 3),(gen_random_uuid(), 'a4c38fa6-8361-5f40-bf5a-e45ade76af30', NULL, 'Serve immediately while hot.', 4),(gen_random_uuid(), '40ffa67a-8b5a-5bcc-bd6a-c2684b3b2522', NULL, 'Whisk chia seeds, coconut milk, and maple syrup together.', 0),(gen_random_uuid(), '40ffa67a-8b5a-5bcc-bd6a-c2684b3b2522', NULL, 'Pour into two glasses or bowls.', 1),(gen_random_uuid(), '40ffa67a-8b5a-5bcc-bd6a-c2684b3b2522', NULL, 'Refrig